forms.logicScript:
function onSubmit(ctx) {
  // New deals default to the 'Lead' stage when none is chosen.
  if (!ctx.answers.stage) {
    ctx.answers.stage = 'lead';
  }
}

files.content:
:root {
  --bg-0: #0b1020;
  --bg-1: #0f1630;
  --card: rgba(255, 255, 255, 0.04);
  --card-brd: rgba(255, 255, 255, 0.08);
  --card-brd-hi: rgba(255, 255, 255, 0.16);
  --text: #e7ecf5;
  --muted: #93a0bf;
  --faint: #64708f;
  --brand: #6366f1;
  --brand-2: #a855f7;
  --ok: #22c55e;
  --shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
  --radius: 16px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg-0);
  color: var(--text);
  font-family: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
}

* { box-sizing: border-box; }

#app {
  min-height: 100vh;
  background:
    radial-gradient(1100px 520px at 12% -8%, rgba(99, 102, 241, 0.20), transparent 60%),
    radial-gradient(900px 500px at 110% 0%, rgba(168, 85, 247, 0.16), transparent 55%),
    linear-gradient(180deg, var(--bg-1), var(--bg-0));
}

.fl-loading {
  display: grid;
  place-items: center;
  min-height: 100vh;
  color: var(--muted);
  font-size: 15px;
  letter-spacing: 0.01em;
}

.wrap {
  max-width: 1160px;
  margin: 0 auto;
  padding: 28px 22px 64px;
}

/* Header */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 26px;
}
.brand { display: flex; align-items: center; gap: 14px; min-width: 0; }
.brand .logo {
  width: 46px; height: 46px; border-radius: 13px; flex: none;
  background: linear-gradient(135deg, var(--brand), var(--brand-2));
  display: grid; place-items: center;
  font-weight: 800; font-size: 20px; color: #fff;
  box-shadow: var(--shadow);
}
.brand h1 { margin: 0; font-size: 20px; font-weight: 700; letter-spacing: -0.01em; }
.brand .sub { margin: 2px 0 0; font-size: 13px; color: var(--muted); }
.topbar .who { display: flex; align-items: center; gap: 10px; }
.who .greet { font-size: 13px; color: var(--muted); text-align: right; }
.who .greet b { color: var(--text); font-weight: 600; }

.btn {
  appearance: none; border: 1px solid var(--card-brd-hi);
  background: var(--card); color: var(--text);
  padding: 9px 14px; border-radius: 11px; font-size: 13px; font-weight: 600;
  cursor: pointer; transition: transform .08s ease, border-color .15s ease, background .15s ease;
}
.btn:hover { border-color: var(--brand); background: rgba(99, 102, 241, 0.12); }
.btn:active { transform: translateY(1px); }
.btn.primary {
  border-color: transparent;
  background: linear-gradient(135deg, var(--brand), var(--brand-2));
  color: #fff;
  box-shadow: 0 8px 20px rgba(99, 102, 241, 0.35);
}
.btn.primary:hover { filter: brightness(1.06); background: linear-gradient(135deg, var(--brand), var(--brand-2)); }

/* Stat cards */
.stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 22px;
}
.stat {
  background: var(--card);
  border: 1px solid var(--card-brd);
  border-radius: var(--radius);
  padding: 18px 18px 16px;
  position: relative;
  overflow: hidden;
}
.stat::after {
  content: ""; position: absolute; inset: 0 0 auto 0; height: 3px;
  background: linear-gradient(90deg, var(--brand), var(--brand-2));
  opacity: .8;
}
.stat .k { font-size: 12px; color: var(--muted); text-transform: uppercase; letter-spacing: .06em; }
.stat .v { font-size: 27px; font-weight: 800; margin-top: 8px; letter-spacing: -0.02em; }
.stat .d { font-size: 12px; color: var(--faint); margin-top: 4px; }
.stat.win::after { background: linear-gradient(90deg, var(--ok), #4ade80); }
.stat.win .v { color: #86efac; }

/* Layout grid */
.grid {
  display: grid;
  grid-template-columns: 1.35fr 1fr;
  gap: 16px;
}
.panel {
  background: var(--card);
  border: 1px solid var(--card-brd);
  border-radius: var(--radius);
  padding: 20px;
}
.panel h2 {
  margin: 0 0 4px; font-size: 15px; font-weight: 700; letter-spacing: -0.01em;
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
}
.panel .hint { margin: 0 0 16px; font-size: 12px; color: var(--faint); }

/* Pipeline bars */
.bars { display: flex; flex-direction: column; gap: 14px; }
.bar-row { display: grid; grid-template-columns: 92px 1fr auto; align-items: center; gap: 12px; }
.bar-row .name { font-size: 13px; color: var(--muted); font-weight: 600; }
.bar-track {
  height: 12px; border-radius: 99px; background: rgba(255, 255, 255, 0.06); overflow: hidden;
}
.bar-fill {
  height: 100%; border-radius: 99px; width: 0;
  transition: width .7s cubic-bezier(.2, .7, .2, 1);
  background: linear-gradient(90deg, var(--brand), var(--brand-2));
}
.bar-row .amt { font-size: 13px; font-weight: 700; text-align: right; min-width: 74px; }
.bar-row .amt small { display: block; font-weight: 500; color: var(--faint); font-size: 11px; }

/* Recent deals */
.list { display: flex; flex-direction: column; gap: 10px; }
.item {
  display: flex; align-items: center; gap: 12px;
  padding: 12px 12px; border-radius: 12px;
  border: 1px solid var(--card-brd);
  background: rgba(255, 255, 255, 0.02);
}
.item .main { min-width: 0; flex: 1; }
.item .t { font-size: 14px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.item .m { font-size: 12px; color: var(--muted); margin-top: 3px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.item .val { font-size: 14px; font-weight: 800; white-space: nowrap; }

.badge {
  display: inline-block; padding: 3px 9px; border-radius: 99px;
  font-size: 11px; font-weight: 700; letter-spacing: .02em;
  border: 1px solid transparent;
}

/* Quick actions */
.actions { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 12px; margin-top: 4px; }
.action {
  display: flex; flex-direction: column; align-items: flex-start; gap: 8px;
  padding: 16px; border-radius: 14px; cursor: pointer;
  border: 1px solid var(--card-brd); background: rgba(255, 255, 255, 0.03);
  color: var(--text); text-align: left;
  transition: transform .08s ease, border-color .15s ease, background .15s ease;
}
.action:hover { border-color: var(--brand); background: rgba(99, 102, 241, 0.12); transform: translateY(-2px); }
.action:active { transform: translateY(0); }
.action .ico {
  width: 34px; height: 34px; border-radius: 10px; display: grid; place-items: center;
  background: linear-gradient(135deg, rgba(99,102,241,.9), rgba(168,85,247,.9)); font-size: 18px;
}
.action .lbl { font-weight: 700; font-size: 14px; }
.action .cap { font-size: 12px; color: var(--muted); }

/* Empty state */
.empty {
  text-align: center; color: var(--muted); padding: 26px 12px; font-size: 13px;
  border: 1px dashed var(--card-brd); border-radius: 12px;
}
.empty b { color: var(--text); display: block; margin-bottom: 4px; font-size: 14px; }

.footer { margin-top: 26px; text-align: center; color: var(--faint); font-size: 12px; }

@media (max-width: 900px) {
  .stats { grid-template-columns: repeat(2, 1fr); }
  .grid { grid-template-columns: 1fr; }
}
@media (max-width: 520px) {
  .actions { grid-template-columns: 1fr; }
  .bar-row { grid-template-columns: 78px 1fr auto; }
}

// data.ts — types, pipeline constants, and pure helpers for the CRM dashboard.
// Imported by index.ts with a relative path (proves multi-file bundling).

export interface FieldMeta {
  id: string;
  label: string;
  type: string;
}

export interface FormMeta {
  formId: string;
  displayName: string;
  fields: FieldMeta[];
}

export interface AppContext {
  appName: string;
  appSlug: string;
  forms: FormMeta[];
}

export interface CrmRecord {
  id: string;
  answers: Record<string, unknown>;
  submittedAt: string;
}

export interface StageInfo {
  value: string;
  label: string;
  color: string;
  open: boolean;
}

// Pipeline stages in display order. `value` matches the Deal.stage dropdown value.
export const STAGES: StageInfo[] = [
  { value: "lead", label: "Lead", color: "#64748b", open: true },
  { value: "qualified", label: "Qualified", color: "#6366f1", open: true },
  { value: "proposal", label: "Proposal", color: "#a855f7", open: true },
  { value: "won", label: "Won", color: "#22c55e", open: false },
  { value: "lost", label: "Lost", color: "#ef4444", open: false },
];

export function stageInfo(value: string): StageInfo {
  const found = STAGES.find((s) => s.value === value);
  return found ?? { value, label: value || "Unknown", color: "#64748b", open: true };
}

// Resolve a form by fuzzy displayName match (e.g. base "contact" matches "Contacts").
export function findForm(ctx: AppContext, base: string): FormMeta | undefined {
  const needle = base.trim().toLowerCase();
  return ctx.forms.find((f) => (f.displayName || "").trim().toLowerCase().includes(needle));
}

export function toNumber(value: unknown): number {
  if (typeof value === "number") return Number.isFinite(value) ? value : 0;
  if (typeof value === "string") {
    const n = parseFloat(value.replace(/[^0-9.\-]/g, ""));
    return Number.isFinite(n) ? n : 0;
  }
  return 0;
}

export function toText(value: unknown): string {
  if (value === null || value === undefined) return "";
  if (typeof value === "string") return value;
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  return "";
}

// linked_record answers can arrive as an id string, an array, or an object.
export function linkedId(value: unknown): string {
  if (!value) return "";
  if (typeof value === "string") return value;
  if (Array.isArray(value)) return linkedId(value[0]);
  if (typeof value === "object") {
    const obj = value as Record<string, unknown>;
    return toText(obj.id ?? obj.value ?? obj.recordId ?? "");
  }
  return "";
}

export function formatCurrency(amount: number): string {
  return "$" + Math.round(amount).toLocaleString("en-US");
}

export function formatCompact(amount: number): string {
  const abs = Math.abs(amount);
  if (abs >= 1_000_000) return "$" + (amount / 1_000_000).toFixed(1).replace(/\.0$/, "") + "M";
  if (abs >= 1_000) return "$" + (amount / 1_000).toFixed(1).replace(/\.0$/, "") + "k";
  return "$" + Math.round(amount);
}

export interface StageBucket {
  stage: StageInfo;
  total: number;
  count: number;
}

export function pipelineByStage(deals: CrmRecord[]): StageBucket[] {
  return STAGES.map((stage) => {
    const matching = deals.filter((d) => toText(d.answers["stage"]) === stage.value);
    const total = matching.reduce((sum, d) => sum + toNumber(d.answers["amount"]), 0);
    return { stage, total, count: matching.length };
  });
}

// Build a lookup of Contact record id -> display name for linked-record rendering.
export function contactNameMap(contacts: CrmRecord[]): Record<string, string> {
  const map: Record<string, string> = {};
  for (const c of contacts) {
    const name = toText(c.answers["name"]) || toText(c.answers["company"]) || toText(c.answers["email"]);
    if (c.id) map[c.id] = name || "Unnamed contact";
  }
  return map;
}

// index.ts — entry point. Wires the DOM to the app-scoped FormLogic SDK and
// renders a live sales-pipeline dashboard. Bundled by esbuild (relative imports only).
import {
  AppContext,
  CrmRecord,
  FormMeta,
  contactNameMap,
  findForm,
  formatCompact,
  formatCurrency,
  linkedId,
  pipelineByStage,
  stageInfo,
  toNumber,
  toText,
} from "./data";

interface FormLogicSdk {
  context(): Promise<AppContext>;
  submit(formId: string, answers: Record<string, unknown>): Promise<unknown>;
  records(formId: string, opts?: { limit?: number }): Promise<CrmRecord[]>;
  currentUser(): Promise<{ name?: string; email?: string } | null>;
  navigate(formId: string): void;
  toast: { success(msg: string): void; error(msg: string): void };
  escapeHtml(value: unknown): string;
}

declare global {
  interface Window {
    FormLogic: FormLogicSdk;
  }
}

const FL = window.FormLogic;
const esc = (v: unknown): string => FL.escapeHtml(v);
const root = document.getElementById("app");

void main();

async function main(): Promise<void> {
  if (!root) return;
  if (!FL) {
    root.innerHTML = '<div class="fl-loading">FormLogic SDK unavailable.</div>';
    return;
  }
  try {
    const ctx = await FL.context();
    const user = await FL.currentUser().catch(() => null);

    const contactForm = findForm(ctx, "contact");
    const dealForm = findForm(ctx, "deal");
    const activityForm = findForm(ctx, "activit");

    const [deals, contacts] = await Promise.all([
      dealForm ? FL.records(dealForm.formId, { limit: 500 }) : Promise.resolve([]),
      contactForm ? FL.records(contactForm.formId, { limit: 500 }) : Promise.resolve([]),
    ]);

    render(ctx, user, { contactForm, dealForm, activityForm }, deals, contacts);
  } catch (err) {
    root.innerHTML =
      '<div class="wrap"><div class="empty"><b>Could not load the dashboard</b>' +
      esc(err instanceof Error ? err.message : String(err)) +
      "</div></div>";
  }
}

interface Forms {
  contactForm?: FormMeta;
  dealForm?: FormMeta;
  activityForm?: FormMeta;
}

function render(
  ctx: AppContext,
  user: { name?: string; email?: string } | null,
  forms: Forms,
  deals: CrmRecord[],
  contacts: CrmRecord[]
): void {
  if (!root) return;

  const buckets = pipelineByStage(deals);
  const openPipeline = buckets
    .filter((b) => b.stage.open)
    .reduce((s, b) => s + b.total, 0);
  const wonTotal = buckets.filter((b) => b.stage.value === "won").reduce((s, b) => s + b.total, 0);
  const openCount = deals.filter((d) => stageInfo(toText(d.answers["stage"])).open).length;
  const maxBar = Math.max(1, ...buckets.map((b) => b.total));
  const names = contactNameMap(contacts);

  const greeting = user && (user.name || user.email) ? `<b>${esc(user.name || user.email)}</b>` : "there";

  root.innerHTML = `
    <div class="wrap">
      <header class="topbar">
        <div class="brand">
          <div class="logo">${esc((ctx.appName || "C").charAt(0).toUpperCase())}</div>
          <div>
            <h1>${esc(ctx.appName || "Sales CRM")}</h1>
            <p class="sub">Pipeline overview &middot; welcome back, ${greeting}</p>
          </div>
        </div>
        <div class="who">
          <button class="btn" id="refresh" type="button">Refresh</button>
          <button class="btn primary" id="new-deal" type="button">+ New deal</button>
        </div>
      </header>

      <section class="stats">
        ${statCard("Open pipeline", formatCurrency(openPipeline), `${openCount} active deal${openCount === 1 ? "" : "s"}`, false)}
        ${statCard("Won", formatCurrency(wonTotal), `${buckets.find((b) => b.stage.value === "won")?.count ?? 0} closed`, true)}
        ${statCard("Contacts", String(contacts.length), "in your book", false)}
        ${statCard("Total deals", String(deals.length), "all stages", false)}
      </section>

      <section class="grid">
        <div class="panel">
          <h2>Pipeline value by stage</h2>
          <p class="hint">Sum of deal amounts grouped by stage.</p>
          ${deals.length ? renderBars(buckets, maxBar) : emptyState("No deals yet", "Add your first deal to see the pipeline build up.")}
        </div>

        <div class="panel">
          <h2>Quick add</h2>
          <p class="hint">Jump straight into a form.</p>
          <div class="actions">
            ${actionCard("act-contact", "\u{1F464}", "Contact", "New person", forms.contactForm)}
            ${actionCard("act-deal", "\u{1F4B0}", "Deal", "New opportunity", forms.dealForm)}
            ${actionCard("act-activity", "\u{1F5D3}", "Activity", "Log a touch", forms.activityForm)}
          </div>
        </div>
      </section>

      <section class="grid" style="margin-top:16px">
        <div class="panel">
          <h2>Recent deals</h2>
          <p class="hint">Latest opportunities and their linked contact.</p>
          ${deals.length ? renderRecentDeals(deals, names) : emptyState("No deals yet", "Deals you create will appear here.")}
        </div>

        <div class="panel">
          <h2>Recent contacts</h2>
          <p class="hint">The people most recently added.</p>
          ${contacts.length ? renderRecentContacts(contacts) : emptyState("No contacts yet", "Add a contact to get started.")}
        </div>
      </section>

      <p class="footer">Built with FormLogic &middot; live data from your forms</p>
    </div>
  `;

  wire(forms);
}

function statCard(k: string, v: string, d: string, win: boolean): string {
  return `
    <div class="stat${win ? " win" : ""}">
      <div class="k">${esc(k)}</div>
      <div class="v">${esc(v)}</div>
      <div class="d">${esc(d)}</div>
    </div>`;
}

function renderBars(buckets: ReturnType<typeof pipelineByStage>, maxBar: number): string {
  const rows = buckets
    .map((b) => {
      const pct = Math.max(b.total > 0 ? 4 : 0, Math.round((b.total / maxBar) * 100));
      const grad = `linear-gradient(90deg, ${b.stage.color}, ${b.stage.color}cc)`;
      return `
        <div class="bar-row">
          <span class="name">${esc(b.stage.label)}</span>
          <span class="bar-track"><span class="bar-fill" style="width:${pct}%;background:${grad}"></span></span>
          <span class="amt">${esc(formatCompact(b.total))}<small>${b.count} deal${b.count === 1 ? "" : "s"}</small></span>
        </div>`;
    })
    .join("");
  return `<div class="bars">${rows}</div>`;
}

function renderRecentDeals(deals: CrmRecord[], names: Record<string, string>): string {
  const recent = [...deals].sort(bySubmittedDesc).slice(0, 6);
  const items = recent
    .map((d) => {
      const title = toText(d.answers["title"]) || "Untitled deal";
      const st = stageInfo(toText(d.answers["stage"]));
      const amount = formatCurrency(toNumber(d.answers["amount"]));
      const cid = linkedId(d.answers["contact"]);
      const contactName = cid && names[cid] ? names[cid] : cid ? "Linked contact" : "No contact";
      const badge = `<span class="badge" style="color:${st.color};background:${st.color}22;border-color:${st.color}55">${esc(st.label)}</span>`;
      return `
        <div class="item">
          <div class="main">
            <div class="t">${esc(title)}</div>
            <div class="m">${badge} &middot; ${esc(contactName)}</div>
          </div>
          <div class="val">${esc(amount)}</div>
        </div>`;
    })
    .join("");
  return `<div class="list">${items}</div>`;
}

function renderRecentContacts(contacts: CrmRecord[]): string {
  const recent = [...contacts].sort(bySubmittedDesc).slice(0, 6);
  const items = recent
    .map((c) => {
      const name = toText(c.answers["name"]) || "Unnamed";
      const company = toText(c.answers["company"]);
      const email = toText(c.answers["email"]);
      const sub = [company, email].filter(Boolean).join(" · ") || "—";
      return `
        <div class="item">
          <div class="main">
            <div class="t">${esc(name)}</div>
            <div class="m">${esc(sub)}</div>
          </div>
        </div>`;
    })
    .join("");
  return `<div class="list">${items}</div>`;
}

function actionCard(id: string, ico: string, lbl: string, cap: string, form?: FormMeta): string {
  const disabled = form ? "" : ' aria-disabled="true" style="opacity:.5;cursor:not-allowed"';
  return `
    <button class="action" type="button" id="${esc(id)}"${disabled}>
      <span class="ico">${ico}</span>
      <span class="lbl">${esc(lbl)}</span>
      <span class="cap">${esc(cap)}</span>
    </button>`;
}

function emptyState(title: string, msg: string): string {
  return `<div class="empty"><b>${esc(title)}</b>${esc(msg)}</div>`;
}

function bySubmittedDesc(a: CrmRecord, b: CrmRecord): number {
  return String(b.submittedAt || "").localeCompare(String(a.submittedAt || ""));
}

function wire(forms: Forms): void {
  const go = (form?: FormMeta): void => {
    if (form) {
      FL.navigate(form.formId);
    } else {
      FL.toast.error("That form isn't available in this app.");
    }
  };

  document.getElementById("refresh")?.addEventListener("click", () => {
    FL.toast.success("Refreshing…");
    void main();
  });
  document.getElementById("new-deal")?.addEventListener("click", () => go(forms.dealForm));
  document.getElementById("act-contact")?.addEventListener("click", () => go(forms.contactForm));
  document.getElementById("act-deal")?.addEventListener("click", () => go(forms.dealForm));
  document.getElementById("act-activity")?.addEventListener("click", () => go(forms.activityForm));
}
